try:
    import re
    import datetime
    vars['identity_gate'] = 'pending'
    vars['current_verify_field'] = ''
    body = config.get('body', dict())
    if isinstance(body, dict):
        field = str(body.get('field', ''))
        answer = str(body.get('answer', '')).strip()
        vars['current_verify_field'] = field
        if field == 'phone_last4':
            words = dict(zero='0', oh='0', one='1', two='2', three='3', four='4', five='5', six='6', seven='7', eight='8', nine='9')
            parts = re.split(r'[\s,-]+', answer.lower())
            converted = ''.join(words.get(p, p) for p in parts)
            if re.fullmatch(r'[0-9]{4}', converted):
                body['answer'] = converted
        elif field == 'date_of_birth':
            match = re.fullmatch(r'(\d{1,2})[/.\-](\d{1,2})[/.\-](\d{4})', answer)
            if match:
                body['answer'] = datetime.date(int(match.group(3)), int(match.group(2)), int(match.group(1))).isoformat()
            elif re.fullmatch(r'\d{4}-\d{2}-\d{2}', answer):
                body['answer'] = datetime.date.fromisoformat(answer).isoformat()
        config['body'] = body
except Exception:
    vars['identity_gate'] = 'pending'

